# ============================================================================
#  seed_vc_iraqi_windows.ps1 - Windows 10/11 edition (NVIDIA GPU recommended)
#  Run:  powershell -ExecutionPolicy Bypass -File seed_vc_iraqi_windows.ps1
#  Or:   irm <this-script-url> | iex
#  Env:  $env:IRAQI_YODAS_HOURS="200"; $env:IRAQI_STEPS="3000"; ...
#        (messages are English-only to avoid Windows codepage issues)
# ============================================================================
$ErrorActionPreference = "Stop"
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

function Say($m)  { Write-Host "[iraqi] $m" -ForegroundColor Cyan }
function Fail($m) { Write-Host "[iraqi][ERROR] $m" -ForegroundColor Red; exit 1 }

$Root       = if ($env:IRAQI_DATA_ROOT)   { $env:IRAQI_DATA_ROOT }   else { Join-Path $PWD "iraqi_seedvc" }
$Steps      = if ($env:IRAQI_STEPS)       { $env:IRAQI_STEPS }       else { "3000" }
$Batch      = if ($env:IRAQI_BATCH)       { $env:IRAQI_BATCH }       else { "2" }
$SaveEvery  = if ($env:IRAQI_SAVE_EVERY)  { $env:IRAQI_SAVE_EVERY }  else { "250" }
$YodasHours = if ($env:IRAQI_YODAS_HOURS) { $env:IRAQI_YODAS_HOURS } else { "200" }
$RunName    = if ($env:IRAQI_RUN_NAME)    { $env:IRAQI_RUN_NAME }    else { "iraqi_v1" }
$Nproc      = [Math]::Max(2, $env:NUMBER_OF_PROCESSORS - 1)
$Workers    = if ($env:IRAQI_WORKERS)     { $env:IRAQI_WORKERS }     else { [string]$Nproc }
$FetchW     = if ($env:IRAQI_FETCH_WORKERS) { $env:IRAQI_FETCH_WORKERS } else { [string][Math]::Min(16, [Math]::Max(8, $Nproc * 2)) }

New-Item -ItemType Directory -Force -Path $Root | Out-Null
Set-Location $Root

# ---------------------------------------------------------------- GPU check
$GpuOk = $false
try { $null = & nvidia-smi 2>&1; if ($LASTEXITCODE -eq 0) { $GpuOk = $true } } catch {}
if (-not $GpuOk) { Say "WARNING: no NVIDIA GPU detected - data will be prepared, training SKIPPED." }

function Refresh-Path {
  $env:Path = [Environment]::GetEnvironmentVariable("Path","Machine") + ";" +
              [Environment]::GetEnvironmentVariable("Path","User")
  $links = "$env:LOCALAPPDATA\Microsoft\WinGet\Links"
  if ((Test-Path $links) -and ($env:Path -notlike "*$links*")) { $env:Path = "$links;" + $env:Path }
}
function Need($cmd) { Refresh-Path; Get-Command $cmd -ErrorAction SilentlyContinue }
function Winget-Install($id) {
  Say "  winget install $id ..."
  try { & winget install -e --id $id --accept-source-agreements --accept-package-agreements --silent | Out-Null }
  catch { Say "  winget install of $id failed - install it manually and re-run" }
  Refresh-Path
}

# ---------------------------------------------------------------- stage 1
Say "stage 1/8: system dependencies (git, python 3.10, ffmpeg)"
if (-not (Need "git"))     { if (Get-Command winget -ErrorAction SilentlyContinue) { Winget-Install "Git.Git" } }
if (-not (Need "python"))  { if (Get-Command winget -ErrorAction SilentlyContinue) { Winget-Install "Python.Python.3.10" } }
if (-not (Need "ffmpeg"))  { if (Get-Command winget -ErrorAction SilentlyContinue) { Winget-Install "Gyan.FFmpeg" } }
if (-not (Need "git"))     { Fail "git not found - install from https://git-scm.com then re-run" }
if (-not (Need "python"))  { Fail "python not found - install Python 3.10 (python.org) then re-run" }
if (-not (Need "ffmpeg"))  { Fail "ffmpeg not found - run: winget install Gyan.FFmpeg  then re-run" }
$Py = (Need "python").Source
Say "  python: $(& $Py --version) | ffmpeg OK | git OK"

# ---------------------------------------------------------------- stage 2
Say "stage 2/8: Python venv + PyTorch 2.4.0 (CUDA 12.1)"
if (-not (Test-Path "$Root\venv")) { & $Py -m venv "$Root\venv" }
$Py = "$Root\venv\Scripts\python.exe"
& $Py -m pip install --quiet --upgrade pip 2>$null
if (-not (& $Py -c "import torch; assert torch.__version__.startswith('2.4.')" 2>$null)) {
  Say "  installing pinned PyTorch 2.4.0 cu121 (about 2.5 GB download) ..."
  & $Py -m pip install --quiet torch==2.4.0 torchvision==0.19.0 torchaudio==2.4.0 --index-url https://download.pytorch.org/whl/cu121
  if ($LASTEXITCODE -ne 0) {
    Say "  exact pins failed - retrying with latest CUDA wheels ..."
    & $Py -m pip install --quiet torch torchvision torchaudio --index-url https://download.pytorch.org/whl/cu121
    if ($LASTEXITCODE -ne 0) { Fail "PyTorch install failed" }
  }
}
& $Py -m pip install --quiet numpy==1.26.4 scipy==1.13.1 librosa==0.10.2 soundfile==0.12.1 `
  munch==4.0.0 einops==0.8.0 transformers==4.46.3 pyyaml tqdm requests pyarrow==17.0.0 huggingface_hub
if ($LASTEXITCODE -ne 0) {
  Say "  exact pins failed - retrying with latest versions ..."
  & $Py -m pip install --quiet numpy scipy librosa soundfile munch einops transformers pyyaml tqdm requests pyarrow==17.0.0 huggingface_hub
  if ($LASTEXITCODE -ne 0) { Fail "python dependencies install failed" }
}
& $Py -c "import torch,transformers,librosa,soundfile,munch,pyarrow,huggingface_hub,yaml; print('  torch', torch.__version__, '| cuda:', torch.cuda.is_available())"

# ---------------------------------------------------------------- stage 3
Say "stage 3/8: Seed-VC repository"
$SeedVc = "$Root\seed-vc"
if (-not (Test-Path "$SeedVc\train.py")) {
  & git clone --depth 1 https://github.com/Plachtaa/seed-vc.git "$SeedVc"
  if ($LASTEXITCODE -ne 0) { Fail "git clone of Seed-VC failed" }
}
if (-not (Test-Path "$SeedVc\train.py")) { Fail "Seed-VC repo incomplete" }

# ---------------------------------------------------------------- stage 4
Say "stage 4/8: writing embedded data pipeline (Iraqi manifests included)"
$PipeB64 = @'

'@
[IO.File]::WriteAllText("$Root\iraqi_pipeline.py",
  [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($PipeB64)))
& $Py -c "import ast; ast.parse(open(r'$Root\iraqi_pipeline.py', encoding='utf-8').read()); print('  pipeline OK')"
if ($LASTEXITCODE -ne 0) { Fail "embedded pipeline is corrupted" }
$Pipe = "$Root\iraqi_pipeline.py"

# ---------------------------------------------------------------- stage 5
if ($env:IRAQI_SKIP_SMALL -ne "1") {
  Say "stage 5/8: downloading clean Iraqi speech sets (youssef / shiekh / safaa)"
  & $Py $Pipe small --root $Root
  if ($LASTEXITCODE -ne 0) { Fail "small datasets stage failed" }
} else { Say "stage 5/8: skipped (IRAQI_SKIP_SMALL=1)" }

# ---------------------------------------------------------------- stage 6
if ($YodasHours -ne "0") {
  Say "stage 6/8: ranged-fetching Iraqi speech from espnet/yodas3 (target: $YodasHours h)"
  & $Py $Pipe yodas --root $Root --hours $YodasHours --workers $FetchW
  if ($LASTEXITCODE -ne 0) { Fail "yodas fetch stage failed (re-run to resume)" }
} else { Say "stage 6/8: skipped (IRAQI_YODAS_HOURS=0)" }

# ---------------------------------------------------------------- stage 7
Say "stage 7/8: cutting + segmenting + encoding training data (24 kHz mono opus)"
& $Py $Pipe prep --root $Root --out "$Root\data\iraqi_finetune" --workers $Workers
if ($LASTEXITCODE -ne 0) { Fail "preprocessing stage failed (re-run to resume)" }
$DataDir = "$Root\data\iraqi_finetune"
$NFiles  = (Get-ChildItem "$DataDir" -Recurse -Filter *.ogg -ErrorAction SilentlyContinue).Count
Say "  training corpus: $NFiles clips ready"
if ($NFiles -lt 50) { Fail "too few training clips ($NFiles) - check the logs above" }

# ---------------------------------------------------------------- stage 8
$RunDir = "$SeedVc\runs\$RunName"
if ($env:IRAQI_SKIP_TRAIN -eq "1") {
  Say "stage 8/8: training skipped (IRAQI_SKIP_TRAIN=1) - data ready at $DataDir"
} elseif (-not $GpuOk) {
  Say "stage 8/8: training skipped (no NVIDIA GPU) - data ready at $DataDir"
} elseif (Test-Path "$RunDir\ft_model.pth") {
  Say "stage 8/8: fine-tuned model already exists (skip training)"
} else {
  Say "stage 8/8: fine-tuning seed-uvit-tat-xlsr-tiny on Iraqi speech"
  Say "  prefetching model checkpoints ..."
  & $Py $Pipe prefetch --repo $SeedVc
  Push-Location $SeedVc
  & $Py train.py --config configs/presets/config_dit_mel_seed_uvit_xlsr_tiny.yml `
    --dataset-dir $DataDir --run-name $RunName --batch-size $Batch `
    --max-steps $Steps --save-every $SaveEvery --num-workers 0 --gpu 0
  $trainRc = $LASTEXITCODE
  Pop-Location
  if ($trainRc -ne 0) { Fail "training failed - re-run the script to resume from the last checkpoint" }
  Say "  verifying fine-tuned checkpoint with a real inference pass ..."
  & $Py $Pipe verify --repo $SeedVc --run-dir $RunDir --ckpt "$RunDir\ft_model.pth" `
    --config "$SeedVc\configs\presets\config_dit_mel_seed_uvit_xlsr_tiny.yml" --data-dir $DataDir
  if ($LASTEXITCODE -ne 0) { Say "  (verify could not run - weights are still exported)" }
}

# ---------------------------------------------------------------- export
$ExportPath = ""
if (Test-Path "$RunDir\ft_model.pth") {
  Say "exporting fine-tuned weights + config + report ..."
  $ExportPath = (& $Py $Pipe export --run-dir $RunDir `
    --config "$SeedVc\configs\presets\config_dit_mel_seed_uvit_xlsr_tiny.yml" `
    --data-dir $DataDir) | Select-Object -Last 1
  if ($ExportPath) { Say "EXPORTED MODEL: $ExportPath" }
}

Say "ALL DONE."
if ($ExportPath) {
  Say "  - data      : $DataDir"
  Say "  - weights   : $ExportPath"
  Say "  - inference : cd $SeedVc; python inference.py --checkpoint <weights>\seed_uvit_tat_xlsr_tiny_iraqi.pth --config <weights>\config_dit_mel_seed_uvit_xlsr_tiny.yml --source a.wav --target b.wav --output out"
}
